parameters.jsCode:
const lead = $json;

let score = 0;
const reasons = [];

// Service area
if (lead.in_service_area === true) {
  score += 20;
  reasons.push("Inside service area +20");
}

// Property ownership
if (
  lead.ownership_status &&
  lead.ownership_status.toLowerCase() === "owner"
) {
  score += 15;
  reasons.push("Property owner +15");
}

// Electricity spend
if (
  typeof lead.monthly_electricity_spend === "number" &&
  lead.monthly_electricity_spend >= 2000
) {
  score += 15;
  reasons.push("Electricity spend >= R2000 +15");
}

// Timeline
if (
  lead.timeline === "ASAP" ||
  lead.timeline === "0-30 days"
) {
  score += 20;
  reasons.push("Near-term timeline +20");
} else if (lead.timeline === "1-3 months") {
  score += 10;
  reasons.push("1-3 month timeline +10");
}

// Clear solar requirement
if (
  lead.primary_goal &&
  lead.primary_goal !== "Unknown"
) {
  score += 10;
  reasons.push("Clear solar requirement +10");
}

// Payment path
if (
  ["Cash", "Finance", "Either"].includes(
    lead.payment_preference
  )
) {
  score += 10;
  reasons.push("Payment path identified +10");
}



// Lead temperature
let lead_temperature;

if (score >= 60) {
  lead_temperature = "HOT";
} else if (score >= 35) {
  lead_temperature = "WARM";
} else {
  lead_temperature = "COLD";
}

// Special override
if (lead.in_service_area === false) {
  lead_temperature = "HUMAN_REVIEW";
}

return [
  {
    json: {
      ...lead,
      lead_score: score,
      lead_temperature,
      score_reasons: reasons
    }
  }
];

