let lead;


if (typeof $json.text === "string") {
  try {
    lead = JSON.parse($json.text);
  } catch (error) {
    throw new Error(
      "AI output was not valid JSON: " + $json.text
    );
  }
} else {
  lead = $json;
}

const requiredFields = [
  "name",
  "location",
  "property_type",
  "ownership_status",
  "monthly_electricity_spend",
  "primary_goal",
  "existing_equipment",
  "timeline",
  "payment_preference"
];

const missingFields = requiredFields.filter((field) => {
  const value = lead[field];

  return (
    value === null ||
    value === undefined ||
    value === "" 
  );
});

return [
  {
    json: {
      ...lead,
      missing_fields: missingFields,
      qualification_complete: missingFields.length === 0
    }
  }
];

const lead = $json;

const questions = {
  name: "What name should I use for your solar enquiry?",
  location: "Which suburb or area is the property in?",
  property_type: "Is this for a house, townhouse, apartment, or another type of property?",
  ownership_status: "Do you own the property, or are you currently renting?",
  monthly_electricity_spend: "Roughly how much do you spend on electricity in a typical month?",
  primary_goal: "What matters most to you: reducing your electricity bill, backup power during outages, or both?",
  existing_equipment: "Do you already have any solar panels, inverter, battery, or generator installed?",
  timeline: "When would you ideally like the system installed?",
  payment_preference: "Would you prefer cash, finance, either option, or are you still deciding?"
};

const nextField = lead.next_missing_field ?? null;

return [
  {
    json: {
      ...lead,
      next_question: nextField ? questions[nextField] : null   //ternary operator (basically If nextField exists, give me the question associated with that field. Otherwise, give me null.)
    }
  }
];

const lead = $json;

// V1 simulated SolarFlow SA service areas
const serviceAreas = [
  "midrand",
  "johannesburg",
  "pretoria",
  "centurion"
];

const location =
  (lead.location || "").toLowerCase().trim();

const inServiceArea = serviceAreas.some(area =>
  location.includes(area)
);

return [{
  json: {
    ...lead,
    in_service_area: inServiceArea
  }
}];

// Existing lead row coming from Supabase
let existing;

// New lead path
try {
  existing = $('Create New Lead').item.json;
} catch (e) {}

// Existing lead path
if (!existing || !existing.id) {
  try {
    existing = $('Find Existing Lead').item.json;
  } catch (e) {}
}

if (!existing) {
  throw new Error('Could not find existing Supabase lead state');
}

// Parse AI output
let raw = $json.text;

if (typeof raw === 'string') {
  raw = raw
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
}

let update;

try {
  update =
    typeof raw === 'string'
      ? JSON.parse(raw)
      : raw;
} catch (error) {
  throw new Error(
    'AI output was not valid JSON: ' + raw
  );
}

const latestMessage =
  $('Incoming Solar Message').item.json.body.customer_message
    ?.toLowerCase()
    .trim() || '';

const noEquipmentPatterns = [
  "don't have existing equipment",
  "do not have existing equipment",
  "don't have any solar equipment",
  "do not have any solar equipment",
  "no existing equipment",
  "no solar equipment",
  "no solar system"
];

if (
  (!update.existing_equipment ||
    update.existing_equipment === null) &&
  noEquipmentPatterns.some(pattern =>
    latestMessage.includes(pattern)
  )
) {
  update.existing_equipment = "None";
}

const mentionsBackup =
  latestMessage.includes('backup') ||
  latestMessage.includes('battery') ||
  latestMessage.includes('load shedding') ||
  latestMessage.includes('loadshed') ||
  latestMessage.includes('load-shedding');

const mentionsBillReduction =
  latestMessage.includes('reduce') ||
  latestMessage.includes('lower') ||
  latestMessage.includes('save') ||
  latestMessage.includes('saving') ||
  latestMessage.includes('bill') ||
  latestMessage.includes('electricity cost');

const mentionsPriceResearch =
  latestMessage.includes('price') ||
  latestMessage.includes('prices') ||
  latestMessage.includes('pricing') ||
  latestMessage.includes('quote') ||
  latestMessage.includes('cost') ||
  latestMessage.includes('researching') ||
  latestMessage.includes('someday') ||
  latestMessage.includes('future');

if (!update.primary_goal || update.primary_goal === null) {
  if (mentionsBackup && mentionsBillReduction) {
    update.primary_goal = 'Bill reduction + backup';
  } else if (mentionsBackup) {
    update.primary_goal = 'Backup power';
  } else if (mentionsBillReduction) {
    update.primary_goal = 'Bill reduction';
  } else if (mentionsPriceResearch) {
    update.primary_goal = 'Price research';
  }
}

if (
  typeof update.monthly_electricity_spend === 'string' &&
  update.monthly_electricity_spend.trim() !== ''
) {
  const numericSpend = Number(
    update.monthly_electricity_spend.replace(/[^0-9.]/g, '')
  );

  if (Number.isFinite(numericSpend)) {
    update.monthly_electricity_spend = numericSpend;
  }
}

// IMPORTANT:
// null from AI means "not mentioned", so don't overwrite
// valid existing Supabase values with null.
const cleanedUpdate = {};

for (const [key, value] of Object.entries(update)) {
  if (
    value !== null &&
    value !== undefined &&
    value !== ''
  ) {
    cleanedUpdate[key] = value;
  }
}

const merged = {
  ...existing,
  ...cleanedUpdate
};

return [
  {
    json: merged
  }
];

